<meta name="viewport" content="width=device-width, initial-scale=1"><title>Spend Radar dashboard</title><style>
:root{{--bg:#fbfaf7;--card:#fff;--fg:#1d1f21;--muted:#5d6166;--line:#dedbd3;--accent:#2f5d8a;--bad:#a33a2b;--ok:#2e6b3f}}
