                len(decs), sum(d["chosen"] != d["default"] for d in decs)) + "".join(
                f"<li><code>{_e(d['task_id'])}</code> chose <b>{_e(d['chosen'])}</b>"
                f"{' (rule default: ' + _e(d['default']) + ')' if d['chosen'] != d['default'] else ''}"
                f" — {_e((d.get('reason') or '')[:160])}</li>" for d in decs) + "</ul></details>"
        if Path(f"runs/{r['run_id']}/report.html").exists():
            extra += f"<p><a href='../runs/{_e(r['run_id'])}/report.html'>Open the full report</a> (local file)</p>"
    return (f"<article class='run'><header><code>{_e(r['run_id'])}</code> <span class='tag'>{_e(r['variant'])}</span>"
            f"<span class='muted'> commit {_e(r['git_sha'])}</span></header>"
            f"<div class='stats'><div><b>{caught}/{total}</b><small>planted errors caught</small></div>"
            f"<div><b>{_e(fa)}</b><small>false alarms</small></div>"
            f"<div><b>{_e(r['unsupported_numbers_in_report'])}</b><small>unsourced numbers</small></div>"
            f"<div><b>{_e(r['llm_calls'])}</b><small>LLM calls · {_e(r.get('fallback_hops', 0))} fallbacks</small></div>"
            f"<div><b>{r['crustdata_credits']:.1f}</b><small>Crustdata credits</small></div></div>"
            f"<ul class='checks'>{cells}</ul>"
            f"<p class='muted'>neatlogs trace <code>{_e(r['trace_id'])}</code> · scorecard <code>{_e(r['scorecard'])}</code></p>"
            f"{extra}</article>")


def build() -> Path:
    runs = _load_runs()
    by_ds: dict[str, list[dict]] = {}
    for r in runs:
        by_ds.setdefault(r["dataset"], []).append(r)
    order = ["acme"] + sorted(k for k in by_ds if k != "acme")
    summary_rows = []
    sections = []
    for ds in [d for d in order if d in by_ds]:
        name, industry = _company(ds)
        rs = by_ds[ds]
        first, last = rs[0], rs[-1]
        summary_rows.append(
            f"<tr><td><b>{_e(name)}</b><br><small class='muted'>{_e(industry)}</small></td>"
            f"<td>{first['planted_caught']}/{first['planted_total']}<br><small class='muted'>{_e(first['variant'])}</small></td>"
            f"<td>{last['planted_caught']}/{last['planted_total']}<br><small class='muted'>{_e(last['variant'])}</small></td>"
            f"<td>{_e(last.get('false_alarms', '—'))}</td><td>{len(rs)}</td></tr>")
        sections.append(f"<section><h2>{_e(name)} <small class='muted'>{_e(industry)}</small></h2>"
                        + "".join(_run_card(r) for r in reversed(rs)) + "</section>")
    page = f"""<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1"><title>Spend Radar dashboard</title><style>
:root{{--bg:#fbfaf7;--card:#fff;--fg:#1d1f21;--muted:#5d6166;--line:#dedbd3;--accent:#2f5d8a;--bad:#a33a2b;--ok:#2e6b3f}}
@media (prefers-color-scheme: dark){{:root{{--bg:#141618;--card:#1b1e21;--fg:#e8e6e1;--muted:#a3a7ac;--line:#30343a;--accent:#8ab4e0;--bad:#e3826f;--ok:#7fc495}}}}
*{{box-sizing:border-box}}body{{background:var(--bg);color:var(--fg);font:15px/1.5 ui-sans-serif,system-ui,sans-serif;max-width:1100px;margin:0 auto;padding:24px 16px}}
h1{{font-size:1.7rem;margin:0 0 .2rem}}h2{{margin-top:2.2rem;border-bottom:1px solid var(--line);padding-bottom:.3rem}}
.muted{{color:var(--muted)}}small{{font-size:.8rem}}code{{font-size:.85em;word-break:break-all}}a{{color:var(--accent)}}
table{{border-collapse:collapse;width:100%;margin-top:1rem}}th,td{{border-bottom:1px solid var(--line);padding:8px;text-align:left;vertical-align:top}}
.run{{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:14px 16px;margin:14px 0}}
.run header{{display:flex;gap:10px;flex-wrap:wrap;align-items:baseline}}.tag{{background:color-mix(in srgb,var(--accent) 14%,transparent);color:var(--accent);border-radius:99px;padding:1px 10px;font-size:.8rem}}
.stats{{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:10px;margin:12px 0}}
.stats div{{border:1px solid var(--line);border-radius:8px;padding:8px 10px}}.stats b{{display:block;font-size:1.35rem}}.stats small{{color:var(--muted)}}
.checks{{list-style:none;padding:0;display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:4px 16px}}
.checks li span{{display:inline-block;width:1.4em;font-weight:700}}.ok span{{color:var(--ok)}}.miss{{color:var(--bad)}}
ul.plain{{padding-left:1.1rem}}details{{margin-top:6px}}summary{{cursor:pointer;color:var(--accent)}}
</style></head><body>
<h1>Spend Radar — eval dashboard</h1>
<p class="muted">Every run below was scored against a ground-truth file the agent never reads. Acme is the company the agent was
built against; the others are held-out fictional companies in other industries, with real competitors from Crustdata.
Generated {datetime.now().strftime('%Y-%m-%d %H:%M')} from <code>evidence/evals/</code>. All company finance data is fictional.</p>
<table><thead><tr><th>Company</th><th>First scored run</th><th>Latest run</th><th>False alarms (latest)</th><th>Runs</th></tr></thead>
<tbody>{''.join(summary_rows)}</tbody></table>
{''.join(sections)}
</body></html>"""
    OUT.write_text(page, encoding="utf-8")
    return OUT

